#!/usr/bin/env python3
"""Generate the support site from verified release copy. No analytics or form backend."""
import html, json, os, sys
from pathlib import Path
root = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root / 'build/site-tools'))
import markdown
out = root / 'Website/dist'
out.mkdir(parents=True, exist_ok=True)
email = os.environ.get('NIMLET_PUBLIC_SUPPORT_EMAIL', '')
public = os.environ.get('NIMLET_PUBLIC_SITE') == '1'
if public and not email:
    raise SystemExit('Public build blocked: a verified, authorized support mailbox is required.')
contact = f'<a href="mailto:{html.escape(email, quote=True)}">{html.escape(email)}</a>' if email else 'The support address will be published before launch.'
origin = os.environ.get('NIMLET_SITE_ORIGIN', 'https://nimlet.app').rstrip('/')
nav = '<a class="brand" href="/">Nimlet</a><nav aria-label="Main"><a href="/support/">Support</a><a href="/download/">Mac companion</a><a href="/privacy/">Privacy</a></nav>'
css = '''*{box-sizing:border-box}html{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#101317;color:#ecf0f5;line-height:1.65}body{margin:0}a{color:#8bc9ff;text-underline-offset:.25em}header,main,footer{max-width:1040px;margin:auto;padding:28px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #303640;gap:20px}.brand{font-size:25px;font-weight:750;color:inherit;text-decoration:none}nav{display:flex;gap:24px;flex-wrap:wrap}main{padding-top:55px;min-height:65vh}h1{font-size:clamp(2.3rem,6vw,4.4rem);line-height:1.08;letter-spacing:-.04em;max-width:830px;margin:0 0 28px}h2{font-size:1.55rem;line-height:1.3;margin-top:40px}h3{font-size:1.15rem}p,li{font-size:1rem;max-width:770px}.lead{font-size:1.25rem;color:#bbc8d6;max-width:700px}.status{font-size:.875rem;color:#aac1d7;letter-spacing:.05em;text-transform:uppercase}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:36px}.card{border:1px solid #35404c;border-radius:14px;padding:24px}.card h2{margin-top:0}.button{display:inline-block;padding:12px 20px;border-radius:9px;background:#8bc9ff;color:#091c2d;font-weight:650;text-decoration:none;margin:10px 12px 10px 0}footer{border-top:1px solid #303640;color:#aab5c3;font-size:.875rem}code,pre{overflow-wrap:anywhere;white-space:pre-wrap;font-size:.9em}table{border-collapse:collapse;display:block;overflow:auto;max-width:100%}td,th{padding:10px;border:1px solid #35404c;text-align:left}.skip{position:absolute;left:-9999px}.skip:focus{left:15px;top:10px;padding:12px;background:#fff;color:#000}a:focus-visible,summary:focus-visible{outline:3px solid #d1ebff;outline-offset:4px}details{max-width:800px;border-bottom:1px solid #35404c;padding:18px 0}summary{cursor:pointer;font-size:1.1rem;font-weight:600}@media(max-width:620px){header{align-items:flex-start;flex-direction:column}header,main,footer{padding:22px}main{padding-top:36px}.grid{grid-template-columns:1fr}nav{gap:16px}h1{font-size:2.6rem}}'''
(out/'style.css').write_text(css)
(out/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#101317"/><text x="32" y="46" text-anchor="middle" font-size="43" font-family="Arial" font-weight="700" fill="#8bc9ff">N</text></svg>')
def page(route,title,description,body):
    folder=out/route;folder.mkdir(parents=True,exist_ok=True)
    (folder/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(description,quote=True)}"><meta name="robots" content="noindex"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{origin}/{route}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header>{nav}</header><main id="main">{body}</main><footer>Nimlet · iPhone and your own Mac<br>Support: {contact}</footer></body></html>''')
page('', 'Nimlet — Your Mac coding workspace, at hand', 'Control your own Mac coding workspace from your iPhone over the local network.', '''<p class="status">Preparing for launch</p><h1>Your Mac workspace.<br>At hand.</h1><p class="lead">Switch between coding tools, speak to the right target, and see the window you’re controlling. Nimlet turns your iPhone into a console for your own Mac.</p><a class="button" href="/support/">See how it works</a><a href="/download/">Mac requirements</a><div class="grid"><section class="card"><h2>Try your real workflow</h2><p>Target switching, voice and text input, pointer controls, live previews and approval decisions. Connect both devices on the same local network.</p></section><section class="card"><h2>Everything is open during the beta</h2><p>Send a message to several targets, attach images, and capture and annotate your Mac’s screen. Nothing is paywalled while Nimlet is being tested.</p></section></div><p>Requires iOS 26 or later and macOS 14 or later. Keep Nimlet open during use and your Mac awake. No AI model or AI service subscription is included.</p>''')
page('download','Mac companion — Nimlet','Install requirements for the Nimlet Mac companion.', '''<p class="status">Mac companion</p><h1>One phone.<br>Your own Mac.</h1><p class="lead">The companion receives your input and provides window previews. It stays in the menu bar.</p><section class="card"><h2>Download available at launch</h2><p>The public installer is being prepared. There is no public download yet.</p></section><h2>Requirements</h2><ul><li>macOS 14 or later, on Apple silicon or Intel.</li><li>iPhone with iOS 26 or later.</li><li>Both devices on the same local network.</li><li>Accessibility permission for input; Screen Recording permission for previews and captures.</li></ul><h2>Installation</h2><ol><li>Download the companion when it becomes available and move Nimlet to Applications.</li><li>Open Nimlet and follow the permission prompts.</li><li>Read the pairing code in the menu bar, enter it on the phone, then approve that phone on the Mac.</li></ol><p><a href="/support/">Pairing and troubleshooting</a></p>''')
page('support','Support — Nimlet','Pair your iPhone and Mac, understand permissions, and troubleshoot Nimlet.', f'''<p class="status">Setup & support</p><h1>Get connected.</h1><p class="lead">Start with both devices on the same local network and a blank document on your Mac.</p><ol><li>Install the Mac companion and allow Accessibility when prompted.</li><li>Open Nimlet on your iPhone and allow Local Network access.</li><li>Select your Mac and enter the code shown in its menu bar.</li><li>Approve the phone by name on the Mac.</li><li>Add TextEdit as a target and send a short sentence. Check the intended document.</li></ol><details open><summary>My Mac doesn’t appear</summary><p>Keep the companion running and the Mac awake. Check Local Network permissions. Guest Wi-Fi can block communication between devices. You can enter a local IP address if discovery is unavailable.</p></details><details><summary>Connected, but clicks or typing do nothing</summary><p>Check Accessibility permission for the installed Mac companion. Confirm your selected app or pane still exists and can receive input. A send receipt alone does not prove that the intended document changed.</p></details><details><summary>The preview is blank</summary><p>Enable Screen Recording for the Mac companion and follow any instruction to reopen it. Check that the selected window is available.</p></details><details><summary>Speech is unavailable</summary><p>Check microphone and speech permissions, language settings, and downloaded speech assets. Use the keyboard while troubleshooting. On-device recognition is preferred; fallback recognition may send audio to Apple.</p></details><details><summary>Agents, hooks and approvals</summary><p>On the Mac, open Settings → Agents in Nimlet. One click pairs the bundled command-line tool and installs the Claude Code hooks that tell the phone when a run finishes and ask it before a command runs. The hooks find their target from the tmux pane the agent runs in.</p></details><details><summary>Updating the Mac companion</summary><p>Nimlet’s menu says when a newer build is available. Download it, quit Nimlet, replace the copy in Applications and open it again; pairing and approved phones are kept. The phone tells you too, if it is newer than the Mac.</p></details><details><summary>Does it work over cellular or in the background?</summary><p>This release supports local-network connections. Keep Nimlet open while using it. iOS can suspend background apps, so Nimlet does not promise background monitoring or new agent alerts after suspension.</p></details><h2>Contact</h2><p>{contact}</p><p>Include both app versions, OS versions, the action you tried, and the exact error. Remove private text, pairing codes and addresses from screenshots. Never send passwords or private keys.</p><p><a href="/privacy/">Privacy and data removal</a></p>''')
policy=markdown.markdown((root/'PRIVACY.md').read_text(),extensions=['tables','fenced_code'])
page('privacy','Privacy — Nimlet','How Nimlet handles speech, local connections, purchases and data stored on your devices.', '<p class="status">Release candidate policy · September 27, 2026</p>'+policy)
(out/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
print('Built 4 pages, stylesheet and favicon. Public contact configured:',bool(email))
